question:
What does async/await do?
async Task Main() {
  await Task.Delay(100);
  Console.WriteLine("Done");
}

What is an async deadlock?
async Task Main() {
  var result = GetDataAsync().Result;
  Console.WriteLine(result);
}
async Task<string> GetDataAsync() {
  await Task.Delay(100);
  return "Data";
}

What does Task.Run do?
async Task Main() {
  var result = await Task.Run(() => 5 + 3);
  Console.WriteLine(result);
}

What does ConfigureAwait(false) do?
async Task Method() {
  await Task.Delay(100).ConfigureAwait(false);
  Console.WriteLine("Done");
}

What does Task.WhenAll do?
async Task Main() {
  var t1 = Task.Delay(50);
  var t2 = Task.Delay(100);
  await Task.WhenAll(t1, t2);
  Console.WriteLine("All done");
}

What does Task.WhenAny do?
async Task Main() {
  var t1 = Task.Delay(50);
  var t2 = Task.Delay(100);
  var completed = await Task.WhenAny(t1, t2);
  Console.WriteLine("First done");
}

What does CancellationToken do?
async Task Main() {
  var cts = new CancellationTokenSource();
  var token = cts.Token;
  var task = LongRunningAsync(token);
  cts.Cancel();
  await task;
}
async Task LongRunningAsync(CancellationToken token) {
  while (!token.IsCancellationRequested) {
    await Task.Delay(100);
  }
}

What does ValueTask do?
ValueTask<int> GetNumber() => new ValueTask<int>(42);
var result = await GetNumber();
Console.WriteLine(result);

What is async state machine?
async Task Method() {
  await Task.Delay(100);
  Console.WriteLine("A");
  await Task.Delay(100);
  Console.WriteLine("B");
}

What does async void do?
async void ButtonClick() {
  await Task.Delay(100);
  Console.WriteLine("Click");
}
